import{_ as e,o as d,c as r,ag as a}from"./chunks/framework.DaCm-iTo.js";const g=JSON.parse('{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"modules/strengthen/commands.md","filePath":"modules/strengthen/commands.md","lastUpdated":null}'),o={name:"modules/strengthen/commands.md"};function c(n,t,h,s,l,i){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to &quot;命令与权限&quot;">​</a></h1><p>EmakiStrengthen 的主命令是 <code>/emakistrengthen</code>，别名 <code>/estrengthen</code>。玩家主要打开强化 GUI；管理员用命令检查主手装备、刷新展示、设置星级、清理状态和发放强化材料。</p><h2 id="命令列表" tabindex="-1">命令列表 <a class="header-anchor" href="#命令列表" aria-label="Permalink to &quot;命令列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th><th>权限</th></tr></thead><tbody><tr><td><code>/estrengthen help</code></td><td>显示帮助。</td><td>基础。</td></tr><tr><td><code>/estrengthen open</code></td><td>打开强化 GUI。</td><td><code>emakistrengthen.use</code></td></tr><tr><td><code>/estrengthen reload</code></td><td>重载配置、GUI、语言和配方。</td><td><code>reload</code> 或 <code>admin</code></td></tr><tr><td><code>/estrengthen inspect [player]</code></td><td>检查指定玩家或自己的主手物品。</td><td><code>use</code> 或 <code>admin</code></td></tr><tr><td><code>/estrengthen refresh [player]</code></td><td>刷新指定玩家或自己的物品展示。</td><td><code>admin</code></td></tr><tr><td><code>/estrengthen setstar &lt;star&gt; [recipe]</code></td><td>设置执行者主手物品星级；没有 player 参数。</td><td><code>admin</code></td></tr><tr><td><code>/estrengthen clearstate</code></td><td>清除执行者主手强化层，仅玩家可执行。</td><td><code>admin</code></td></tr><tr><td><code>/estrengthen clearcrack</code></td><td>清除执行者主手锻印值，仅玩家可执行。</td><td><code>admin</code></td></tr><tr><td><code>/estrengthen givecatalyst &lt;material&gt; [amount] [player]</code></td><td>发放强化材料。</td><td><code>admin</code></td></tr><tr><td>`/estrengthen debug &lt;status</td><td>player</td><td>module</td></tr></tbody></table><h2 id="权限节点" tabindex="-1">权限节点 <a class="header-anchor" href="#权限节点" aria-label="Permalink to &quot;权限节点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>emakistrengthen.use</code></td><td>true</td><td>使用基础强化功能。</td></tr><tr><td><code>emakistrengthen.reload</code></td><td>op</td><td>重载配置。</td></tr><tr><td><code>emakistrengthen.debug</code></td><td>op</td><td>调试命令。</td></tr><tr><td><code>emakistrengthen.admin</code></td><td>op</td><td>管理员功能。</td></tr></tbody></table><h2 id="先用哪个命令" tabindex="-1">先用哪个命令 <a class="header-anchor" href="#先用哪个命令" aria-label="Permalink to &quot;先用哪个命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>先执行</th><th>目的</th></tr></thead><tbody><tr><td>玩家要强化装备</td><td><code>/estrengthen open</code></td><td>打开强化 GUI。</td></tr><tr><td>修改了配方、GUI 或语言</td><td><code>/estrengthen reload</code></td><td>重载运行配置。</td></tr><tr><td>装备强化状态不对</td><td><code>/estrengthen inspect</code></td><td>查看主手物品的强化层和匹配配方。</td></tr><tr><td>展示没有刷新</td><td><code>/estrengthen refresh &lt;player&gt;</code></td><td>重建玩家物品展示。</td></tr><tr><td>测试某个星级效果</td><td><code>/estrengthen setstar &lt;star&gt; [recipe]</code></td><td>直接设置执行者主手物品星级。</td></tr><tr><td>调试异常状态</td><td><code>/estrengthen debug ...</code></td><td>查看模块、玩家或全局调试信息。</td></tr></tbody></table><h2 id="管理建议" tabindex="-1">管理建议 <a class="header-anchor" href="#管理建议" aria-label="Permalink to &quot;管理建议&quot;">​</a></h2><ul><li><code>setstar</code>、<code>clearstate</code>、<code>clearcrack</code> 都操作执行者主手物品。执行前先确认手持的是测试装备。</li><li><code>refresh</code> 只解决展示未更新，不会替你修正错误配方。</li><li>修改配方后先 reload，再用测试装备验证成功、失败、保护材料、星级写入和属性写入。</li></ul>',10)])])}const u=e(o,[["render",c]]);export{g as __pageData,u as default};
